func (s *SysAdminRoleRepo) DeleteIndexCache(ctx context.Context, data ...*yanxue_model.SysAdminRole) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, s.cache.Key(CacheSysAdminRoleByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[s.cache.Key(CacheSysAdminRoleByAdminIDPrefix, item.AdminID)] = struct{}{}
			KeyMap[s.cache.Key(CacheSysAdminRoleByRoleIDPrefix, item.RoleID)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := s.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
